mapper.select:
select report_id, elder_id, elder_name, report_type, report_title, period_start, period_end,
       score, risk_level, summary, model_source, model_name, status, error_msg,
       archived_url, tenant_id, del_flag, create_by, create_time, update_by, update_time, remark
from biz_health_report
where del_flag = '0'

	and elder_id = #{elderId}


	and elder_name like concat('%', #{elderName}, '%')


	and report_type = #{reportType}


	and risk_level = #{riskLevel}


	and status = #{status}

order by report_id desc

select checkin_id, apply_no, elder_name, id_card, care_level, suggest_care_level, self_care, mental_state, disease, assessment_result, assessor, assess_time, room_id, bed_id, nurse_ids, contract_no, contract_start, contract_end, checkin_date, apply_status, tenant_id from biz_checkin where del_flag = '0'
and id_card = #{idCard}
and elder_name = #{elderName}
order by checkin_id desc limit 1

select count(1) from biz_service_order
where elder_id = #{elderId} and del_flag = '0'
and service_time >= #{start}
and service_time <= #{end}

select count(1) from biz_service_order
where elder_id = #{elderId} and status = '2' and del_flag = '0'
and service_time >= #{start}
and service_time <= #{end}

select coalesce(sum(amount), 0) from biz_service_order
where elder_id = #{elderId} and del_flag = '0'
and service_time >= #{start}
and service_time <= #{end}

select count(1) from biz_visit
where elder_id = #{elderId} and del_flag = '0'
and visit_date >= #{start}
and visit_date <= #{end}

mapper.insert:
insert into biz_health_report(
	elder_id, elder_name, report_type, report_title, period_start, period_end,
	score, risk_level, summary, content, model_source, model_name, status, error_msg,
	tenant_id, del_flag, create_by, create_time, remark
)values(
	#{elderId}, #{elderName}, #{reportType}, #{reportTitle}, #{periodStart}, #{periodEnd},
	#{score}, #{riskLevel}, #{summary}, #{content}, #{modelSource}, #{modelName}, #{status}, #{errorMsg},
	#{tenantId}, '0', #{createBy}, sysdate(), #{remark}
)

mapper.update:
update biz_health_report
set archived_url = #{archivedUrl}, update_by = #{updateBy}, update_time = sysdate()
where report_id = #{reportId}

update biz_health_report set del_flag = '2', update_time = sysdate()
where report_id in

	#{reportId}
